package com.smartspend.controller;
import com.smartspend.dao.NotificationDAO;import com.smartspend.model.Notification;import com.smartspend.util.*;import javafx.geometry.*;import javafx.scene.control.*;import javafx.scene.layout.*;
public class NotificationsView extends VBox {private final NotificationDAO dao=new NotificationDAO();private final int uid=Session.getUser().getId();private final VBox list=new VBox(10);public NotificationsView(){setPadding(new Insets(5,30,30,30));setSpacing(15);Button all=UI.ghost("Mark all as read");all.setOnAction(e->{dao.markAllRead(uid);load();});getChildren().addAll(UI.title("Notifications"),all,list);load();}private void load(){list.getChildren().clear();for(Notification n:dao.findAll(uid)){Button read=UI.ghost(n.isRead()?"Read":"Mark read");read.setOnAction(e->{dao.markRead(n.getId(),uid);load();});list.getChildren().add(UI.card(new Label(n.getTitle()),new Label(n.getMessage()),new Label(n.getCreatedAt().toString()),read));}}}
